from typing import Dict

def normalize_payload(payload: Dict) -> Dict:
    return {"plaintext": payload["plaintext"]}

def normalize_response(response: Dict) -> Dict:
    return {"ciphertext": response["ciphertext"]}

import os
from google.cloud import kms

def key_usage_summary(config=None):
    config = config or {}
    client = kms.KeyManagementServiceClient()
    name = client.crypto_key_path(config["project_id"], config["location"], config["key_ring"], config["key_id"])
    response = client.get_crypto_key(request={"name": name})
    return {"usage_summary": response.usage_summary}

import re

def payload_safety(plaintext):
    if re.search(r'\bunsafe\b', plaintext, re.IGNORECASE):
        return {"is_safe": False}
    return {"is_safe": True}

import base64

def crypto_audit_embedding(ciphertext, audit_note):
    embedded_note = base64.b64encode(audit_note.encode()).decode()
    return {"ciphertext": ciphertext, "audit_note": embedded_note}

from google.cloud import translate_v2 as translate

def compliance_note_translate(note, target_language):
    client = translate.Client()
    result = client.translate(note, target_language=target_language)
    return {"translated_note": result['translatedText']}
